const config = $('Configuracao').first().json;
const state = $getWorkflowStaticData('global');
state.itemsById = state.itemsById || {};

function firstArray(value) {
  if (Array.isArray(value)) return value;
  const candidates = [
    value?.results,
    value?.items,
    value?.data,
    value?.products,
    value?.ads,
    value?.data?.results,
    value?.data?.items,
  ];
  return candidates.find(Array.isArray) || [];
}

function toNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const cleaned = String(value)
    .replace(/\s/g, '')
    .replace(/R\$/gi, '')
    .replace(/\./g, '')
    .replace(',', '.')
    .replace(/[^0-9.-]/g, '');
  const number = Number(cleaned);
  return Number.isFinite(number) ? number : null;
}

function pick(record, paths) {
  for (const path of paths) {
    const value = path.split('.').reduce((current, key) => current?.[key], record);
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return '';
}

function money(value, currency) {
  if (value === null || value === undefined) return 'preco indisponivel';
  return `${currency} ${Number(value).toFixed(2)}`;
}

const payload = items.length === 1 ? items[0].json : items.map(item => item.json);
const records = firstArray(payload);
const now = new Date().toISOString();
const minPercentChange = Number(config.minPercentChange || 0);
const output = [];

for (const record of records) {
  const itemId = String(pick(record, ['id', 'item_id', 'sku', 'url', 'permalink', 'link', 'title', 'name'])).trim();
  if (!itemId) continue;

  const title = String(pick(record, ['title', 'name', 'description']) || itemId).trim();
  const price = toNumber(pick(record, ['price', 'amount', 'current_price', 'sale_price', 'value', 'prices.price']));
  const itemUrl = String(pick(record, ['permalink', 'url', 'link', 'href'])).trim();
  const imageUrl = String(pick(record, ['thumbnail', 'image', 'picture', 'image_url', 'pictures.0.url'])).trim();
  const seller = String(pick(record, ['seller.nickname', 'seller_name', 'store_name'])).trim();
  const availability = String(pick(record, ['available_quantity', 'availability', 'status'])).trim();

  const previous = state.itemsById[itemId];
  const previousPrice = previous?.price ?? null;
  let eventType = null;
  let priceDiff = null;
  let percentDiff = null;

  if (!previous) {
    eventType = 'novo_anuncio';
  } else if (price !== null && previousPrice !== null && price !== previousPrice) {
    priceDiff = Number((price - previousPrice).toFixed(2));
    percentDiff = previousPrice === 0 ? null : Number(((priceDiff / previousPrice) * 100).toFixed(2));
    eventType = price < previousPrice ? 'queda_preco' : 'aumento_preco';
  }

  state.itemsById[itemId] = {
    title,
    price,
    itemUrl,
    lastSeenAt: now,
    source: config.sourceName,
    query: config.queryName
  };

  if (!eventType) continue;
  if (percentDiff !== null && Math.abs(percentDiff) < minPercentChange) continue;

  const eventLabel = eventType === 'novo_anuncio'
    ? 'Novo anuncio'
    : eventType === 'queda_preco'
      ? 'Queda de preco'
      : 'Aumento de preco';

  const previousLine = previous
    ? `Preco anterior: ${money(previousPrice, config.currency)}\nVariacao: ${priceDiff > 0 ? '+' : ''}${priceDiff} (${percentDiff > 0 ? '+' : ''}${percentDiff}%)\n`
    : '';

  const message = `[${config.sourceName}] ${eventLabel}\n${title}\nPreco atual: ${money(price, config.currency)}\n${previousLine}${itemUrl ? `Link: ${itemUrl}` : 'Link indisponivel'}`;

  output.push({
    json: {
      checked_at: now,
      source: config.sourceName,
      query: config.queryName,
      event_type: eventType,
      item_id: itemId,
      title,
      price,
      previous_price: previousPrice,
      price_diff: priceDiff,
      percent_diff: percentDiff,
      currency: config.currency,
      item_url: itemUrl,
      image_url: imageUrl,
      seller,
      availability,
      message,
      raw_json: JSON.stringify(record),
      spreadsheet_id: config.spreadsheetId,
      sheet_name: config.sheetName,
      telegram_chat_id: config.telegramChatId,
      gmail_to: config.gmailTo
    }
  });
}

const keys = Object.keys(state.itemsById);
if (keys.length > 1000) {
  keys
    .sort((a, b) => String(state.itemsById[a].lastSeenAt).localeCompare(String(state.itemsById[b].lastSeenAt)))
    .slice(0, keys.length - 1000)
    .forEach(key => delete state.itemsById[key]);
}

state.lastExecutionAt = now;
return output;
